          data-testid="rate-form-pct"
          inputmode="decimal"
          [value]="pctInput()"
          (input)="pctInput.set($any($event.target).value); error.set(null)"
        />
        <button type="submit" data-testid="rate-form-submit">Set rate</button>
        @if (error(); as err) {
          <p role="alert" data-testid="rate-form-error">{{ err }}</p>
