              <th scope="row">{{ g }}</th>
              <td [attr.data-testid]="'rate-current-' + g">
                <span [attr.data-testid]="byGrade().has(g) ? 'rate-pct' : null">{{ byGrade().get(g) ?? 'n/a' }}</span>
              </td>
